param([string]$OutputDirectory=$PSScriptRoot)
$null=New-Item -ItemType Directory -Path $OutputDirectory -Force
$ErrorActionPreference = 'Stop'
$compiler = Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
& "$PSScriptRoot\make-icon.ps1"
& $compiler /nologo /optimize+ /target:winexe "/resource:$PSScriptRoot\assets\discord.png,Brand.Discord" "/resource:$PSScriptRoot\assets\whatsapp.png,Brand.WhatsApp" /win32manifest:"$PSScriptRoot\app.manifest" /win32icon:"$PSScriptRoot\CaptureStudio.ico" /out:"$OutputDirectory\CaptureStudio.exe" /r:System.Windows.Forms.dll /r:System.Drawing.dll /r:System.Web.Extensions.dll /r:System.Net.Http.dll /r:"$env:WINDIR\System32\WinMetadata\Windows.ApplicationModel.winmd" /r:"$env:WINDIR\System32\WinMetadata\Windows.Foundation.winmd" /r:"$env:WINDIR\System32\WinMetadata\Windows.Storage.winmd" /r:"$env:WINDIR\Microsoft.NET\Framework64\v4.0.30319\System.Runtime.WindowsRuntime.dll" /r:"$env:WINDIR\Microsoft.NET\assembly\GAC_MSIL\System.Runtime\v4.0_4.0.0.0__b03f5f7f11d50a3a\System.Runtime.dll" /r:"$env:WINDIR\Microsoft.NET\assembly\GAC_MSIL\System.Runtime.InteropServices.WindowsRuntime\v4.0_4.0.0.0__b03f5f7f11d50a3a\System.Runtime.InteropServices.WindowsRuntime.dll" /r:"$env:WINDIR\Microsoft.NET\Framework64\v4.0.30319\WPF\PresentationFramework.dll" /r:"$env:WINDIR\Microsoft.NET\Framework64\v4.0.30319\WPF\PresentationCore.dll" /r:"$env:WINDIR\Microsoft.NET\Framework64\v4.0.30319\WPF\WindowsBase.dll" "$PSScriptRoot\CaptureStudio.cs" "$PSScriptRoot\WindowCapture.cs" "$PSScriptRoot\EditorFeatures.cs" "$PSScriptRoot\ModernUi.cs" "$PSScriptRoot\Viewport.cs" "$PSScriptRoot\Productivity.cs" "$PSScriptRoot\LocalEffects.cs" "$PSScriptRoot\DesktopIdentity.cs" "$PSScriptRoot\WindowsIntegration.cs" "$PSScriptRoot\WindowsTheme.cs" "$PSScriptRoot\NextVersion.cs" "$PSScriptRoot\HotkeySettings.cs" "$PSScriptRoot\InterfaceReview.cs" "$PSScriptRoot\MultiCapture.cs" "$PSScriptRoot\Sharing.cs" "$PSScriptRoot\SharePanel.cs" "$PSScriptRoot\OcrSelection.cs" "$PSScriptRoot\CaptureDelay.cs" "$PSScriptRoot\ClearCapture.cs" "$PSScriptRoot\Updates.cs" "$PSScriptRoot\VersionInfo.cs" "$PSScriptRoot\SetupCloseProtocol.cs" "$PSScriptRoot\InstallerShutdown.cs" "$PSScriptRoot\ImageProcessing.cs" "$PSScriptRoot\ImageAdjustments.cs"
if ($LASTEXITCODE -ne 0) { throw 'Compilation impossible' }
& $compiler /nologo /optimize+ /target:exe /out:"$OutputDirectory\SetupBridge.exe" "$PSScriptRoot\installer\SetupBridge.cs" "$PSScriptRoot\SetupCloseProtocol.cs"
if ($LASTEXITCODE -ne 0) { throw 'Compilation du processus de fermeture impossible' }

if([IO.Path]::GetFullPath($OutputDirectory) -ne [IO.Path]::GetFullPath($PSScriptRoot)){
 foreach($name in @('CaptureStudio.ico','CaptureStudio.exe.config','ocr.ps1','Installer.cmd','Installer.ps1','README.md','app.manifest')) {Copy-Item -LiteralPath (Join-Path $PSScriptRoot $name) -Destination (Join-Path $OutputDirectory $name) -Force}
}
